            $tenant = isset($row['tenant']) ? new TenantRef(uid: $row['tenant']) : null;
            $urgent = isset($row['urgent']) ? !! $row['urgent'] : null;
            if (null === $urgent) {
                throw ConstraintException::ofError('not-null', ['urgent'], [null]);
            }
            $content = $row['content'] ?? null;
